// Rotate 90° CW so text is upright for OCR + draw (original is sideways)
func rotate90CW(_ image: CGImage) -> CGImage {
    let w = image.width, h = image.height
    let cs = CGColorSpaceCreateDeviceRGB()
    let ctx = CGContext(data: nil, width: h, height: w, bitsPerComponent: 8, bytesPerRow: 0, space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.translateBy(x: CGFloat(h), y: 0)
    ctx.rotate(by: .pi / 2)
    ctx.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
    return ctx.makeImage()!
}
func rotate90CCW(_ image: CGImage) -> CGImage {
    let w = image.width, h = image.height
    let cs = CGColorSpaceCreateDeviceRGB()
    let ctx = CGContext(data: nil, width: h, height: w, bitsPerComponent: 8, bytesPerRow: 0, space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.translateBy(x: 0, y: CGFloat(w))
    ctx.rotate(by: -.pi / 2)
    ctx.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
    return ctx.makeImage()!
}

