    let n = max(1, min(dark.count, dark.count*2/5))
    var sr=0,sg=0,sb=0
    for i in 0..<n { sr+=dark[i].0; sg+=dark[i].1; sb+=dark[i].2 }
    // estimate character height from vertical run of ink
    var maxRun = 0
    for x in 0..<w {
        var run = 0
        for y in 0..<h {
            if inkMask[y*w+x] { run += 1; maxRun = max(maxRun, run) } else { run = 0 }
