// Build alpha mask from yan glyph: dark pixels = ink
func makeInkAlpha(from img: CGImage, threshold: Int = 140) -> (CGImage, [(Int,Int)]) {
    let w = img.width, h = img.height
    var rgba = [UInt8](repeating:0, count: w*h*4)
    CGContext(data:&rgba, width:w, height:h, bitsPerComponent:8, bytesPerRow:w*4,
              space: CGColorSpaceCreateDeviceRGB(),
              bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
        .draw(img, in: CGRect(x:0,y:0,width:w,height:h))
    var out = rgba
    var inkPixels: [(Int,Int)] = []
    for y in 0..<h {
        for x in 0..<w {
            let i = (y*w+x)*4
            let r=Int(rgba[i]), g=Int(rgba[i+1]), b=Int(rgba[i+2])
            let lum = (r+g+b)/3
            if r > g+45 && r > b+45 { // red stamp — keep transparent
                out[i+3] = 0
                continue
            }
            if lum < threshold {
                // keep original RGB, alpha based on darkness
                let a = UInt8(min(255, max(0, (threshold - lum) * 255 / threshold)))
                out[i] = UInt8(r); out[i+1]=UInt8(g); out[i+2]=UInt8(b); out[i+3]=a
                if a > 80 { inkPixels.append((r,g,b)) }
            } else {
                out[i+3] = 0
            }
        }
    }
    let ctx = CGContext(data:&out, width:w, height:h, bitsPerComponent:8, bytesPerRow:w*4,
                        space: CGColorSpaceCreateDeviceRGB(),
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    return (ctx.makeImage()!, inkPixels)
}
