    for y in y0..<(y0+h) {
        for x in x0..<(x0+w) {
            guard x>=0,y>=0,x<W,y<H else { continue }
            let i = idx(x,y)
            let r=Double(pixels[i]), g=Double(pixels[i+1]), b=Double(pixels[i+2])
            if (r+g+b)/3 > 140 { sr+=r; sg+=g; sb+=b; n+=1 }
