// Mild box blur on the stamped region only (simulate photo softness)
func softRegion(x0:Int, y0:Int, w:Int, h:Int, radius:Int = 1) {
    var copy = pixels
    for y in y0..<(y0+h) {
        for x in x0..<(x0+w) {
            guard x>=radius, y>=radius, x<W-radius, y<H-radius else { continue }
            // only blur pixels we likely touched (darker than paper)
            let i = idx(x,y)
            let lum = (Int(pixels[i])+Int(pixels[i+1])+Int(pixels[i+2]))/3
            if lum > 150 { continue }
            var sr=0,sg=0,sb=0,n=0
            for oy in -radius...radius {
                for ox in -radius...radius {
                    let j = idx(x+ox, y+oy)
                    sr+=Int(copy[j]); sg+=Int(copy[j+1]); sb+=Int(copy[j+2]); n+=1
                }
            }
            // 60% blur, 40% original — light soften
            pixels[i]   = UInt8((Int(copy[i])*2 + sr/n*3)/5)
            pixels[i+1] = UInt8((Int(copy[i+1])*2 + sg/n*3)/5)
            pixels[i+2] = UInt8((Int(copy[i+2])*2 + sb/n*3)/5)
        }
    }
}
