struct Box { var x0:Int; var x1:Int; var y0:Int; var y1:Int }
func findNumBoxes(x0:Int,x1:Int,y0:Int,y1:Int)->[Box]{
    let w=x1-x0
    var col=[Int](repeating:0,count:w)
    for y in y0..<y1 {
        for x in x0..<x1 {
            if dlum(x,y)<100 { col[x-x0]+=1 }
        }
    }
    var boxes:[Box]=[]
    var i=0
    while i<w {
        if col[i]>=3 {
            let s=i
            while i<w && col[i]>=2 { i+=1 }
            let e=i-1
            let ww=e-s+1
            if ww>=5 && ww<=50 {
                var top=y1, bot=y0
                for y in y0..<y1 {
                    for x in (x0+s)...(x0+e) {
                        if dlum(x,y)<100 { top=min(top,y); bot=max(bot,y) }
                    }
                }
                // skip very tall printed chars (full line height Chinese)
                if bot-top+1 <= Int(Double(y1-y0)*0.85) && bot-top+1 >= 8 {
                    boxes.append(Box(x0:x0+s,x1:x0+e,y0:top,y1:bot))
                }
            }
        } else { i+=1 }
    }
    return boxes
}

