/// Fill region by cloning nearby paper patches (preserves grain)
func cloneFill(_ pix: inout [UInt8], W:Int, H:Int, x0:Int, y0:Int, x1:Int, y1:Int, srcX:Int) {
    let h=y1-y0+1, w=x1-x0+1
    for y in y0...y1 {
        for x in x0...x1 {
            // sample from left of region, same y, with small jitter
            let sx = max(0, min(W-1, srcX + ((x-x0) % 5) - 2))
            let sy = max(0, min(H-1, y + ((x+y)%3) - 1))
            let si=(sy*W+sx)*4, di=(y*W+x)*4
            // only use if source is light (paper)
            let v=(Int(pix[si])+Int(pix[si+1])+Int(pix[si+2]))/3
            if v > 175 {
                pix[di]=pix[si]; pix[di+1]=pix[si+1]; pix[di+2]=pix[si+2]
            } else {
                // fallback average paper
                pix[di]=230; pix[di+1]=230; pix[di+2]=230
            }
        }
    }
    _ = (h,w)
}

