func paperAt(_ pix:[UInt8], W:Int, H:Int, x:Int, y:Int)->(UInt8,UInt8,UInt8){
    var rs:[Int]=[],gs:[Int]=[],bs:[Int]=[]
    for oy in -5...5 { for ox in [-12,-8,-4,4,8,12] {
        let xx=min(W-1,max(0,x+ox)), yy=min(H-1,max(0,y+oy))
        let i=(yy*W+xx)*4
        let r=Int(pix[i]),g=Int(pix[i+1]),b=Int(pix[i+2])
        if (r+g+b)/3>200 { rs.append(r); gs.append(g); bs.append(b) }
    }}
    if rs.isEmpty { return (240,240,240) }
    rs.sort(); gs.sort(); bs.sort()
    return (UInt8(rs[rs.count/2]),UInt8(gs[gs.count/2]),UInt8(bs[bs.count/2]))
}

/// Remove short vertical-run dark pixels (dots/bars); keep tall vertical strokes (the 1s)
func removeFlecks(_ pix: inout [UInt8], W:Int, H:Int, x0:Int, x1:Int, y0:Int, y1:Int, minRun:Int) {
    func L(_ x:Int,_ y:Int)->Int {
        guard x>=0,y>=0,x<W,y<H else { return 255 }
        let i=(y*W+x)*4; return (Int(pix[i])+Int(pix[i+1])+Int(pix[i+2]))/3
    }
    // work on a copy of decisions then apply
    var kill = Array(repeating: false, count: (y1-y0+1)*(x1-x0+1))
    for y in y0...y1 {
        for x in x0...x1 {
            if L(x,y) > 145 { continue }
            var a=y,b=y
            while a>y0 && L(x,a-1)<145 { a-=1 }
            while b<y1 && L(x,b+1)<145 { b+=1 }
            if b-a+1 < minRun {
                kill[(y-y0)*(x1-x0+1)+(x-x0)] = true
            }
        }
    }
    for y in y0...y1 {
        for x in x0...x1 {
            if kill[(y-y0)*(x1-x0+1)+(x-x0)] {
                let p=paperAt(pix,W:W,H:H,x:x,y:y)
                let i=(y*W+x)*4; pix[i]=p.0; pix[i+1]=p.1; pix[i+2]=p.2
            }
        }
    }
}

func drawUL(_ pix: inout [UInt8], W:Int, H:Int, x0:Int, x1:Int, y:Int) {
    for x in x0...x1 {
        guard x>=0,x<W,y>=0,y<H else { continue }
        let i=(y*W+x)*4
        if (Int(pix[i])+Int(pix[i+1])+Int(pix[i+2]))/3 > 155 {
            pix[i]=48; pix[i+1]=48; pix[i+2]=48
        }
    }
}

